for _ in range(int(input())):
	(n, k) = map(int, input().split())
	arr = list(map(int, input().split()))
	sorted_arr = sorted(arr)
	if arr == sorted_arr:
		print(0)
		continue
	(index_x, index_y) = (0, 0)
	for i in range(n):
		if arr[i] == i + 1:
			index_x += 1
		else:
			break
	for i in reversed(range(n)):
		if arr[i] == i + 1:
			index_y += 1
		else:
			break
	if n - index_x - index_y <= k:
		print(1)
		continue
	index_y = min(n - index_y - k, n)
	temp1 = arr[0:index_x] + sorted(arr[index_x:index_x + k]) + arr[index_x + k:n]
	arr1 = temp1[0:index_y] + sorted(temp1[index_y:index_y + k]) + temp1[index_y + k:n]
	temp2 = arr[0:index_y] + sorted(arr[index_y:index_y + k]) + arr[index_y + k:n]
	arr2 = temp1[0:index_x] + sorted(temp2[index_x:index_x + k]) + temp2[index_x + k:n]
	print(2) if arr1 == sorted_arr or arr2 == sorted_arr else print(3)
